void __attribute__((constructor)) test_init() {
#ifdef BRAHMA_ENABLE_MPI
  auto test_instance = brahma::MPIIOTest::get_instance();
  auto num_bindings = test_instance->bind<brahma::MPIIOTest>("MPIIOTest", 0);
  printf("MPIIO num_bindings: %zu\n", num_bindings);
#endif
}

void __attribute__((destructor)) test_finalize() {
#ifdef BRAHMA_ENABLE_MPI
  auto test_instance = brahma::MPIIOTest::get_instance();
  printf("MPIIO num_bindings: %zu, api_count: %zu\n",
         test_instance->num_bindings, test_instance->api_count);
  fflush(stdout);
  assert(test_instance->num_bindings == test_instance->api_count);
  size_t unbindings = test_instance->unbind();
  printf("MPIIO unbindings: %zu\n", unbindings);
  printf("finalizing test\n");
#endif
}

void print_stacktrace(int sig) {
  void* array[32];
  size_t size = backtrace(array, 32);
  fprintf(stderr, "Error: signal %d\n", sig);
  backtrace_symbols_fd(array, size, STDERR_FILENO);
  exit(sig);
}

